ROOT=Path(__file__).resolve().parents[1];JOB='job-000001';BASE=Path('shared/reference/message-sets/business-application-header/2021-11-03-v3.0');DOC=BASE/'documents/src-000012';PART=Path('shared/reference/participants');RAW=Path('raw-input/business_application_header/ISO_20022_BusinessApplicationHeader_MUG_v3_0.pdf')
