def meta(kind,**kw):return fm(domain='shared',document_kind=kind,source_ids=['src-000012'],source_edition='Version 3.0, 2021-11-03',**kw)
roles={
'bah-authorised-signatory':dict(title='Person or business entity authorised to sign a Business Message',labels=['person authorised to sign','Business Entity authorised to sign','creator of the Signature'],definition='The person or business entity authorised within the applicable business context to sign the entire Business Message. This is a signature-authorisation role; the source does not identify it with a named institution, the transport sender or a universal job title.',actions='Creates a Signature over the BAH and ISO 20022 Message under agreed signature rules. The guide does not specify who is authorised or which business scenarios must be signed. In the illustrative process the private key signs canonicalized SignedInfo; SignatureValue is calculated as the last creation step.',identifiers='The illustrative KeyInfo carries an X509v3 certificate containing the validation key. KeyInfo itself has an Id unique within the enclosing XML document. A certificate/key identifies verification material; it is not a universal institutional identifier scheme.',loc='§§4.1–4.2.1 pp28–29; §4.2.6 pp31–32; §4.2.10–4.2.11 p33'),
'bah-signature-verifier':dict(title='Verifier of a BAH Signature',labels=['verifiers of the Signature','receiver in the signature-verification example'],definition='A participant applying the agreed signature structure and verification process to a received Business Message. This functional verification role is scoped to the MUG signature guidelines, not an institution type or proof that every business receiver performs verification itself.',actions='Reconstructs the defined XML contexts, transforms and digests BAH, ISO message and KeyInfo, compares Reference digests, and verifies SignatureValue using SignedInfo and the certificate/public key. A failed comparison or failed verification produces failure. Agrees the signature structure with the creator.',identifiers='Uses the X509v3 certificate/public validation key from KeyInfo under the agreed PKI context. The guide does not specify a verifier identifier scheme.',loc='§4.1–4.2 p28; §4.2.2 pp29–30; §4.2.6 pp31–32; §4.2.12 p33; Figure 5 p35')}
for rid,r in roles.items():
 p=PART/(rid+'.md');other='bah-signature-verifier' if rid=='bah-authorised-signatory' else 'bah-authorised-signatory'
 b=meta('participant',participant_id=rid,aliases=r['labels'],domains=['shared'],message_sets=['business-application-header'],message_families=['head.001'],message_ids=[],source_locations=[r['loc']],flows=['bah-signed-message','bah-signing-business-message','bah-verifying-signature'],limitations=['The authorised person and required signing scenarios are outside the annex scope.','Historical illustrative MUG profile; not silently applied to supplied V04 schema.'])+'# '+r['title']+'\n\n## Definition and role scope\n\n'+r['definition']+' '+cite(p,r['loc'])+'\n\n## Responsibilities and actions\n\n'+r['actions']+' '+cite(p,r['loc'])+'\n\n## Identifiers\n\n'+r['identifiers']+' '+cite(p,r['loc'])+'\n\n## Relationships and applicability\n\nThe '+link(p,PART/(other+'.md'),other)+' is the counterpart role under the agreed signature structure. '+link(p,PART/'bah-sending-messaging-endpoint.md','Sending endpoint')+' and '+link(p,PART/'bah-receiving-messaging-endpoint.md','receiving endpoint')+' are message roles; no equality between those endpoints and the person authorised to sign is asserted. The PKI infrastructure, certification-chain policy and any service/business-area restrictions depend on the implementation context. '+cite(p,'§4.1–4.2.1 p28; §4.2.6 pp31–32')+'\n\n## Flows\n\n'+''.join('- '+link(p,BASE/'flows'/(s+'.md'),'bah-'+s)+'.\n' for s in ['signed-message','signing-business-message','verifying-signature'])+'\n## Evidence and ambiguities\n\nFigure 4 has an apparent reference-connector discrepancy (issue-000017); the source image, textual URI rules and Figure 5 remain separate. '+link(p,Path('tracking/issues.md'),'Issue register')+'. This record does not assign authority to a particular person or institution.\n'
 put(p,b)
# Guide-level signature rules, with precise locators for every substantive rule.
p=Path('shared/reference/concepts/bah-signature-guidelines.md')
b=meta('concept',concept_id='bah-signature-guidelines',message_sets=['business-application-header'],message_families=['head.001'],message_ids=[],source_locations=['MUG Annex A pp28–36'],limitations=['Illustrative historical technical signature guidelines; authority to sign and required business scenarios are outside scope.','Source Figure 4 connector ambiguity issue-000017.'])+'# BAH signature guidelines in the supplied MUG\n\n'
b+='The guide’s Annex A is an illustrative technical model for implementation-specific signature guidelines. It does not change business requirements or decide who may sign and which scenarios require signing. Creator and verifiers must agree the signature structure and service/business-area constraints. '+cite(p,'§4.1–4.2.3 pp28–31')+'\n\n'
b+='The optional Signature covers the Business Message: BAH plus ISO 20022 Message. The guide does not support signing only part of that Business Message. Signature syntax follows the referenced W3C XML Signature standard with contextual constraints. '+cite(p,'§4.2–4.2.1 p28')+'\n\n'
b+='## Structure and references\n\nThe illustrative SignedInfo has three Reference elements: ISO message, BAH and KeyInfo. Their order is irrelevant. '+cite(p,'§4.2.7 p32')+'\n\n'
b+='| Signed resource | Identifying URI rule | Processing/context | Source |\n| --- | --- | --- | --- |\n| ISO 20022 Message | URI attribute absent | Application logic selects the ISO message; exclusive canonicalization precedes digest. The guide uses the one URI-absent Reference allowed by its referenced approach. | §4.2.8 p32 |\n| BAH | URI attribute present and empty | BAH XML context; sign complete BAH except Signature itself. First transform is enveloped-signature, then exclusive canonicalization. | §4.2.9 pp32–33 |\n| KeyInfo | URI fragment references KeyInfo Id | Id should be unique within the enclosing XML document. Exclusive canonicalization precedes digest. Optional Type URI http://www.w3.org/2000/09/xmldsig#KeyInfo need not be further processed. | §4.2.10 p33 |\n\n'+cite(p,'§§4.2.7–4.2.10 pp32–33')+' The guide claims its added KeyInfo Reference is XAdES-BES compliant; that is retained as a historical source claim, not independently certified.\n\n'
b+='KeyInfo must contain the X509v3 certificate with the validation key; it may also contain chain certificates according to allowed PKI infrastructure. It recommends no other KeyInfo elements. KeyInfo itself is signed and has an Id with a unique value. Certificate order is irrelevant. The guide recommends the entire chain; where a specific PKI infrastructure is required, the signing certificate alone is sufficient. It notes that using the environment’s trusted CA root may be preferable to checking a supplied root in a fixed-PKI relationship. '+cite(p,'§4.2.6 pp31–32')+'\n\n'
b+='## Processing and outcomes\n\nApplications may have approval/amendment steps and may create BAH elements after the ISO message. Calculating SignatureValue is the last Business Message creation step; it may occur in the sending flow if the specified process is preserved. Signature creation/verification uses two defined XML contexts, AppHdr and ISO message (for example Document), independently of transport packaging. '+cite(p,'§4.2.11–4.2.12 p33')+'\n\n'
b+='The introductory generic diagram verifies SignatureValue first, then checks the digest. The detailed BAH verification diagram compares the three resource digests before its signature-verification decision. Both source orders are preserved in their own reconstructions. Failed digest comparison or failed verification leads to failure; a successful path requires both. '+cite(p,'Figure 2 p29 and explanation p30; Figure 5 p35')+'\n\n'
b+='## Algorithm table and source examples\n\nThe source offers RSA/SHA-256, SHA-256 and exclusive canonicalization as an illustrative selection and explicitly anticipates algorithm updates. '+link(p,DOC/'tables/tbl-0020.md','Complete algorithm table and literal source spellings')+' preserves all values. This page makes no current cryptographic recommendation. '+cite(p,'§4.2.5 p31')+'\n\n'+link(p,DOC/'examples/signature-xml-example.md','Complete retained signature example')+' preserves the source XML and original page; extracted text has layout artefacts and is not a validated cryptographic fixture. '+cite(p,'§4.5 p36')+'\n\n'
b+='## Navigation and unresolved evidence\n\n'+link(p,BASE/'flows/signing-business-message.md','Signing flow')+' · '+link(p,BASE/'flows/verifying-signature.md','Verification flow')+' · '+link(p,PART/'bah-authorised-signatory.md','Authorised signatory')+' · '+link(p,PART/'bah-signature-verifier.md','Verifier')+'\n\nThe page-34 Figure 4 blue connectors appear to map the ISO-message and KeyInfo digests differently from the text and Figure 5. '+link(p,DOC/'pdf-figures/fig-0033.md','Figure 4 reconstruction')+' retains the apparent artwork and uncertainty; issue-000017 remains open. The MUG uses V03 examples; applicability to supplied head.001.001.04 remains issue-000004.\n'
put(p,b)
# Separate reusable construction and verification flows.
flows={
'signing-business-message':dict(title='Construct the BAH signature as the final creation step',trigger='An application has a Business Message to sign under agreed implementation guidelines.',pre='BAH and ISO message content are ready after any business approval/amendment. Signature creator and verifiers agree the signature structure and contextual constraints; signing authority is determined outside the annex.',loc='§4.1 p28; §§4.2.6–4.2.12 pp31–33; Figure 4 p34',rows=[('1','Authorised signatory / signing implementation','Obtain the Business Message and construct KeyInfo with certificate and unique Id.','Local construction; no new business-message exchange specified.'),('2','Signing implementation','Extract BAH, remove enveloped Signature, canonicalize and calculate its digest.','BAH context.'),('3','Signing implementation','Extract the ISO 20022 Message, canonicalize and calculate its digest.','ISO message context.'),('4','Signing implementation','Canonicalize KeyInfo and calculate its digest.','KeyInfo context.'),('5','Signing implementation','Place the three digests in References using text-defined URI rules: BAH empty URI, ISO message URI absent, KeyInfo #Id.','Figure 4 connector discrepancy remains issue-000017.'),('6','Authorised signatory / signing implementation','Canonicalize SignedInfo, perform the signing algorithm, insert SignatureValue as final creation step.','Private-key signing in the introductory figure.'),('7','Sending messaging endpoint','Send the resulting signed Business Message to the receiving endpoint.','Sending endpoint → receiving endpoint; generic transport shown in Figure 2.')],alternative='Figure 4’s apparent connector mapping is not silently corrected. Text-defined URI rules and drawn connectors are recorded separately. The source supplies no business cancellation/reversal or signer-authorisation failure workflow.',outcome='SignatureValue has been inserted into the completed Business Message; receipt or successful verification is a separate flow.',figs=[31,32,33]),
'verifying-signature':dict(title='Verify a received BAH signature',trigger='A participant receives a signed Business Message to verify under agreed signature rules.',pre='Creator and verifier agree the structure and contextual constraints. The two XML contexts and the certificate/public validation key must be available according to the guide’s profile.',loc='§4.1–4.2 p28; Figure 2 p29; §4.2.2 p30; §§4.2.6–4.2.12 pp31–33; Figure 5 p35',rows=[('1','Receiving endpoint / verifier','Make the received Business Message available.','Prior exchange: sending endpoint → receiving endpoint.'),('2','Signature verifier','Extract BAH, apply enveloped-signature transform and canonicalization, then calculate digest.','Compare against empty-URI Reference.'),('3','Signature verifier','Extract ISO message, canonicalize and calculate digest.','Compare against URI-absent Reference.'),('4','Signature verifier','Extract KeyInfo, canonicalize and calculate digest.','Compare against #KeyInfo-id Reference.'),('5','Signature verifier','Decision: do all Reference comparisons succeed? No → verification failed. Yes → continue.','Figure 5 p35.'),('6','Signature verifier','Obtain SignatureValue, SignedInfo and certificate; perform verification algorithm.','The explanatory text identifies canonicalized SignedInfo, certified public key and SignatureValue inputs.'),('7','Signature verifier','Decision: algorithm verification successful? No → verification failed; Yes → verification successful.','No external response message is specified by the figure.')],alternative='The introductory generic Figure 2 checks the cryptographic signature before digest comparison. Detailed BAH Figure 5 checks References first. These source variants are preserved. Each negative branch is terminal verification failure; the source does not prescribe a business rejection/cancellation message here.',outcome='Both digest consistency and signature verification pass, or verification fails. Presence of Signature alone does not prove a successful outcome.',figs=[31,34])}
for slug,f in flows.items():
 p=BASE/'flows'/(slug+'.md');ps=['bah-authorised-signatory','bah-signature-verifier','bah-sending-messaging-endpoint','bah-receiving-messaging-endpoint']
 b=meta('business-flow',flow_id='bah-'+slug,source_locations=[f['loc']],domains=['shared'],message_sets=['business-application-header'],message_families=['head.001'],message_ids=[],participants=ps,limitations=['Historical illustrative signature profile; exact V04 applicability not assumed.']+(['Figure 4 connector discrepancy issue-000017.'] if slug.startswith('signing') else []))+'# '+f['title']+'\n\n## Purpose, trigger and preconditions\n\n'+f['trigger']+' '+f['pre']+' '+cite(p,f['loc'])+'\n\n## Participants\n\n'+''.join('- '+link(p,PART/(x+'.md'),x)+'.\n' for x in ps)+'\nSigning implementation is an implementation of the signatory’s technical process, not a newly asserted institution. The source does not say the authorised person must be the messaging endpoint.\n\n## Activities and decisions\n\n| Step | Responsible participant | Activity / decision | Message or context |\n| --- | --- | --- | --- |\n'+''.join('| '+' | '.join(r)+' |\n' for r in f['rows'])+'\nAll steps: '+cite(p,f['loc'])+'\n\n## Alternatives and failures\n\n'+f['alternative']+' '+cite(p,f['loc'])+'\n\n## Outcomes and postconditions\n\n'+f['outcome']+' '+cite(p,f['loc'])+'\n\n## Diagrams and relationships\n\n'+''.join('- '+link(p,DOC/'pdf-figures'/('fig-%04d.md'%n),'fig-%04d'%n)+'.\n' for n in f['figs'])+'\n'+link(p,Path('shared/reference/concepts/bah-signature-guidelines.md'),'Signature structure, rule details and limitations')+' · '+link(p,BASE/'flows/signed-message.md','Signed-message business usage')+'\n'
 put(p,b)
