p=DOC/'index.md';s=(ROOT/p).read_text('utf-8');s+='\n## Curated source tables and diagrams\n\n'+link(p,DOC/'visual-coverage.md','Complete visual coverage, preserved tables, Mermaid reconstructions and limitations')+'.\n';put(p,s)
